example_solution:
class Flatten {
  static flatten(list) {
    return flatten_(list, [])
  }
  static flatten_(list, acc_) {
    for (v in list) {
      if (v==null) continue

      // handle both List and Sequence
      if (v is Sequence) {
        flatten_(v, acc_)
      } else {
        acc_.add(v)
      }
    }
    return acc_
  }
}

test_code:
import "./flatten-array" for Flatten
import "wren-testie/testie" for Testie, Expect

Testie.test("Flatten Array") { |do, skip|
  do.test("empty") {
    Expect.value(Flatten.flatten([]
    )).toEqual([])
  }

  skip.test("no nesting") {
    Expect.value(Flatten.flatten([0, 1, 2]
    )).toEqual([0, 1, 2])
  }

  skip.test("flattens a nested array") {
    Expect.value(Flatten.flatten([[[]]]
    )).toEqual([])
  }

  skip.test("flattens array with just integers present") {
    Expect.value(Flatten.flatten([1, [2, 3, 4, 5, 6, 7], 8]
    )).toEqual([1, 2, 3, 4, 5, 6, 7, 8])
  }

  skip.test("5 level nesting") {
    Expect.value(Flatten.flatten([0, 2, [[2, 3], 8, 100, 4, [[[50]]]], -2]
    )).toEqual([0, 2, 2, 3, 8, 100, 4, 50, -2])
  }

  skip.test("6 level nesting") {
    Expect.value(Flatten.flatten([1, [2, [[3]], [4, [[5]]], 6, 7], 8]
    )).toEqual([1, 2, 3, 4, 5, 6, 7, 8])
  }

  skip.test("null values are omitted from the final result") {
    Expect.value(Flatten.flatten([1, 2, null]
    )).toEqual([1, 2])
  }

  skip.test("consecutive null values at the front of the array are omitted from the final result") {
    Expect.value(Flatten.flatten([null, null, 3]
    )).toEqual([3])
  }

  skip.test("consecutive null values in the middle of the array are omitted from the final result") {
    Expect.value(Flatten.flatten([1, null, null, 4]
    )).toEqual([1, 4])
  }

  skip.test("6 level nested array with null values") {
    Expect.value(Flatten.flatten([0, 2, [[2, 3], 8, [[100]], null, [[null]]], -2]
    )).toEqual([0, 2, 2, 3, 8, 100, -2])
  }

  skip.test("all values in nested array are null") {
    Expect.value(Flatten.flatten([null, [[[null]]], null, null, [[null, null], null], null]
    )).toEqual([])
  }
}
